/**
 * `cta` and each `links[].link` as a manually-typed { text, url } object
 * with no `assetId` -- SquizLink's "manual" path, as opposed to an Asset
 * Tree pick (which the platform stamps with an `assetId`). A bare string is
 * NOT used here even though `resolveLink()` in main.js still accepts one
 * defensively -- real deploy validation rejects a bare string against the
 * live SquizLink schema (confirmed by a failed deploy on a relative-path
 * string value), so manual entry is always the object shape without
 * `assetId`, matching every other object-shaped link default/preview in
 * this component. See banner.spec.md assumption 14.
 */
const withManualLinksArgs = {
  variant: 'primary',
  title: 'Manually-Typed Links',
  description: 'The CTA and every panel link below are manually-typed URLs (no assetId), not Asset Tree picks.',
  cta: { text: 'Manual CTA link', url: 'https://example.com/manual-cta-url' },
  linksHeading: 'Popular',
  links: [
    { link: { text: 'Manual link one', url: 'https://example.com/manual-link-one' } },
    { link: { text: 'Manual link two', url: 'https://example.com/manual-link-two' } },
  ],
};
const withManualLinksHtml = await squiz.markup(withManualLinksArgs);

export const WithManualLinks = {
  render: () => squiz(withManualLinksArgs),
  parameters: {
    docs: {
      description: { story: '`cta` and `links[].link` each set as a { text, url } object with no `assetId` -- SquizLink\'s manual-entry path, as opposed to an Asset Tree pick.' },
      source: { code: withManualLinksHtml, language: 'html', type: 'code' },
    },
  },
};
